"use client";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { cn } from "./lib/cn";
import { cssMs } from "./lib/motion-tokens";
import "./animated-counter.css";
function CounterDigit({
  digit,
  direction,
  reveal,
}: {
  digit: number;
  direction: "up" | "down" | "none";
  reveal: boolean;
}) {
  const column = useRef<HTMLSpanElement>(null),
    first = useRef(true);
  useLayoutEffect(() => {
    const element = column.current;
    if (!element) return;
    const animate = (initial = false) => {
      const tokens = getComputedStyle(element),
        height = element.parentElement!.getBoundingClientRect().height;
      const transform = tokens.transform;
      const offset =
        transform === "none"
          ? 20 + digit
          : -new DOMMatrixReadOnly(transform).m42 / height;
      const start = initial ? 20 : 20 + (((offset % 10) + 10) % 10);
      let end = 20 + digit;
      if (direction === "up" && end < start) end += 10;
      if (direction === "down" && end > start) end -= 10;
      element.getAnimations().forEach((animation) => animation.cancel());
      element.style.transform = `translateY(-${(20 + digit) * 1.2}em)`;
      if (
        !matchMedia("(prefers-reduced-motion: reduce)").matches &&
        (initial || direction !== "none")
      )
        element.animate(
          [
            { transform: `translateY(-${start * 1.2}em)` },
            { transform: `translateY(-${end * 1.2}em)` },
          ],
          {
            duration: cssMs(tokens.getPropertyValue("--duration-deliberate")),
            easing: tokens.getPropertyValue("--ease-out").trim(),
          },
        );
    };
    if (first.current) {
      first.current = false;
      element.style.transform = `translateY(-${(20 + digit) * 1.2}em)`;
      if (reveal) {
        const observer = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) {
              animate(true);
              observer.disconnect();
            }
          },
          { threshold: 0.6 },
        );
        observer.observe(element.parentElement!);
        return () => observer.disconnect();
      }
    } else animate();
  }, [digit, direction, reveal]);
  useEffect(() => {
    const preference = matchMedia("(prefers-reduced-motion: reduce)");
    const cancel = () => {
      if (preference.matches)
        column.current
          ?.getAnimations()
          .forEach((animation) => animation.cancel());
    };
    preference.addEventListener("change", cancel);
    return () => preference.removeEventListener("change", cancel);
  }, []);
  return (
    <span
      data-slot="counter-digit"
      className="inline-block h-[1.2em] w-[1ch] overflow-hidden"
    >
      <span
        ref={column}
        className="block"
        style={
          {
            transform: "translateY(calc(-1.2em * var(--counter-target)))",
            "--counter-target": 20 + digit,
          } as CSSProperties
        }
      >
        {Array.from({ length: 50 }, (_, i) => (
          <span key={i} className="block h-[1.2em] leading-[1.2]">
            {i % 10}
          </span>
        ))}
      </span>
    </span>
  );
}
export function AnimatedCounter({
  value,
  label,
  prefix = "",
  suffix = "",
  decimals = 0,
  locale = "en-US",
  animateOnView = false,
  className,
}: {
  value: number;
  label?: string;
  prefix?: string;
  suffix?: string;
  decimals?: number;
  locale?: string;
  animateOnView?: boolean;
  className?: string;
}) {
  const shell = useRef<HTMLSpanElement>(null),
    content = useRef<HTMLSpanElement>(null);
  useLayoutEffect(() => {
    const measure = () => {
      if (shell.current && content.current)
        shell.current.style.width = `${content.current.offsetWidth}px`;
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (content.current) observer.observe(content.current);
    return () => observer.disconnect();
  }, []);
  const [frame, setFrame] = useState({ value, prior: value });
  if (!Object.is(frame.value, value)) setFrame({ value, prior: frame.value });
  const direction =
    value > frame.prior ? "up" : value < frame.prior ? "down" : "none";
  const text = Number.isFinite(value)
    ? new Intl.NumberFormat(locale, {
        minimumFractionDigits: Math.max(0, Math.min(20, decimals)),
        maximumFractionDigits: Math.max(0, Math.min(20, decimals)),
      }).format(value)
    : "—";
  return (
    <span
      data-slot="animated-counter"
      className={cn("inline-flex flex-col min-w-0", className)}
    >
      {label && (
        <span className="mb-1 text-xs font-medium text-muted-foreground">
          {label}
        </span>
      )}
      <span className="sr-only">
        {prefix}
        {text}
        {suffix}
      </span>
      <span
        ref={shell}
        data-slot="counter-shell"
        aria-hidden="true"
        className="relative inline-block h-[1.2em] overflow-hidden"
      >
        <span
          ref={content}
          className="absolute right-0 inline-flex w-max items-center tabular-nums"
        >
          {prefix}
          {[...text].map((glyph, index) =>
            /\d/.test(glyph) ? (
              <CounterDigit
                key={`digit-${text.length - index}`}
                digit={Number(glyph)}
                direction={direction}
                reveal={animateOnView}
              />
            ) : (
              <span key={`separator-${text.length - index}`}>{glyph}</span>
            ),
          )}
          {suffix}
        </span>
      </span>
    </span>
  );
}

"use client";
import { useEffect, useRef, type ReactNode, type KeyboardEvent } from "react";
import { line, curveMonotoneX } from "d3-shape";
import "./chart-parts.css";
export type ChartSeries = { id: string; label: string; color?: string };
export type ChartDatum = {
  id: string;
  label: string;
  values: Record<string, number | undefined>;
  x?: number;
  event?: string;
};
export type ChartPart = {
  id: string;
  label: string;
  value: number;
  color?: string;
};
export const chartColor = (index: number) => `var(--chart-${(index % 6) + 1})`;
export const numberText = (value: number) =>
  new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 }).format(value);
export function useChartReveal() {
  const root = useRef<HTMLElement>(null);
  useEffect(() => {
    const element = root.current;
    if (!element) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          element.dataset.visible = "true";
          observer.disconnect();
        }
      },
      { threshold: 0.3 },
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return root;
}
export function ChartTable({
  label,
  headers,
  rows,
}: {
  label: string;
  headers: string[];
  rows: (string | number)[][];
}) {
  return (
    <div className="sr-only"><table>
      <caption>{label}</caption>
      <thead>
        <tr>
          {headers.map((header) => (
            <th key={header} scope="col">
              {header}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, index) => (
          <tr key={index}>
            {row.map((cell, column) =>
              column === 0 ? (
                <th key={column} scope="row">
                  {cell}
                </th>
              ) : (
                <td key={column}>{cell}</td>
              ),
            )}
          </tr>
        ))}
      </tbody>
    </table></div>
  );
}
export function ChartMessage({
  loading,
  error,
  empty,
}: {
  loading?: boolean;
  error?: string;
  empty?: boolean;
}) {
  return error || empty ? (
    <p
      role="status"
      className="grid min-h-48 place-items-center text-sm text-muted-foreground"
    >
      {error ?? (loading ? "Loading chart…" : "No data for this range.")}
    </p>
  ) : loading ? (
    <p role="status" className="text-xs text-muted-foreground">
      Updating chart…
    </p>
  ) : null;
}
export function ChartLegend({
  series,
  hidden,
  onToggle,
  active,
  onActive,
}: {
  series: readonly ChartSeries[];
  hidden: readonly string[];
  onToggle: (id: string) => void;
  active?: string | null;
  onActive?: (id: string | null) => void;
}) {
  return (
    <div
      role="group"
      aria-label="Chart series"
      className="flex flex-wrap gap-2"
      onKeyDown={(event) => legendKeys(event)}
    >
      {series.map((item, index) => (
        <button
          key={item.id}
          type="button"
          data-slot="chart-legend-item"
          aria-pressed={!hidden.includes(item.id)}
          onClick={() => onToggle(item.id)}
          onPointerEnter={() => onActive?.(item.id)}
          onPointerLeave={() => onActive?.(null)}
          onFocus={() => onActive?.(item.id)}
          onBlur={() => onActive?.(null)}
          data-active={active === item.id}
        >
          <span
            aria-hidden="true"
            style={{ background: item.color ?? chartColor(index) }}
            className="size-2 rounded-full"
          />
          {item.label}
        </button>
      ))}
    </div>
  );
}
export function legendKeys(event: KeyboardEvent<HTMLElement>) {
  const nodes = [
    ...event.currentTarget.querySelectorAll<HTMLButtonElement>("button"),
  ];
  const index = nodes.indexOf(document.activeElement as HTMLButtonElement);
  const target =
    event.key === "Home"
      ? 0
      : event.key === "End"
        ? nodes.length - 1
        : ["ArrowRight", "ArrowDown"].includes(event.key)
          ? (index + 1) % nodes.length
          : ["ArrowLeft", "ArrowUp"].includes(event.key)
            ? (index - 1 + nodes.length) % nodes.length
            : -1;
  if (target >= 0) {
    event.preventDefault();
    nodes[target]?.focus();
  }
}
export function pointKey(
  event: KeyboardEvent<HTMLElement>,
  active: number | null,
  length: number,
) {
  const index = active ?? length - 1;
  const step = Math.max(1, Math.floor(length / 6));
  const next =
    event.key === "Home"
      ? 0
      : event.key === "End"
        ? length - 1
        : event.key === "PageUp"
          ? index + step
          : event.key === "PageDown"
            ? index - step
            : ["ArrowRight", "ArrowUp"].includes(event.key)
              ? index + 1
              : ["ArrowLeft", "ArrowDown"].includes(event.key)
                ? index - 1
                : event.key === "Escape"
                  ? null
                  : undefined;
  if (next !== undefined) event.preventDefault();
  return next == null ? next : Math.max(0, Math.min(length - 1, next));
}
export function pathFor(
  data: readonly ChartDatum[],
  id: string,
  minimum: number,
  maximum: number,
  hidden = false,
) {
  if (!data.length) return "";
  const first = data[0].x ?? 0,
    last = data[data.length - 1].x ?? data.length - 1;
  const points = data.map((item, index) => ({
    x: (600 * ((item.x ?? index) - first)) / (last - first || 1),
    y: item.values[id],
  }));
  const samples = Array.from({ length: 97 }, (_, index) => {
    const x = (index / 96) * 600;
    let right = points.findIndex((point) => point.x >= x);
    if (right < 0) right = points.length - 1;
    const a = points[Math.max(0, right - 1)],
      b = points[right];
    const valid =
      a.y !== undefined &&
      b.y !== undefined &&
      Number.isFinite(a.y) &&
      Number.isFinite(b.y);
    const value = valid
      ? a.y! + ((b.y! - a.y!) * (x - a.x)) / (b.x - a.x || 1)
      : Number.NaN;
    return [
      x,
      hidden ? 210 : 210 - ((value - minimum) / (maximum - minimum || 1)) * 200,
    ] as [number, number];
  });
  return (
    line<[number, number]>()
      .defined((point) => Number.isFinite(point[1]))
      .x((point) => point[0])
      .y((point) => point[1])
      .curve(curveMonotoneX)(samples) ?? ""
  );
}
export function ChartReadout({ children }: { children: ReactNode }) {
  return (
    <div
      data-slot="chart-readout"
      aria-hidden="true"
      className="mt-3 min-h-11 rounded-surface bg-surface px-3 py-2 text-xs leading-5"
    >
      {children}
    </div>
  );
}

"use client";
import { useState } from "react";
import { AnimatedCounter } from "./animated-counter";
import {
  ChartTable,
  ChartMessage,
  chartColor,
  legendKeys,
  numberText,
  useChartReveal,
  type ChartPart,
} from "./chart-parts";
import { cn } from "./lib/cn";
import "./shared/styles.css";
import "./donut-chart.css";
export function DonutChart({
  label,
  data,
  unit = "",
  className,
  loading,
  error,
}: {
  label: string;
  data: readonly ChartPart[];
  unit?: string;
  className?: string;
  loading?: boolean;
  error?: string;
}) {
  const root = useChartReveal();
  const [hidden, setHidden] = useState<string[]>([]),
    [preview, setPreview] = useState<string | null>(null),
    [pinned, setPinned] = useState<string | null>(null);
  const positive = data.filter(
    (item) => Number.isFinite(item.value) && item.value > 0,
  );
  const whole = positive.reduce((sum, item) => sum + item.value, 0);
  const sorted = [...positive].sort((a, b) => b.value - a.value);
  const small = sorted.filter(
    (item, index) => index >= 5 || item.value / whole < 0.035,
  );
  const grouped = small.length > 1;
  const parts = grouped
    ? [
        ...positive.filter((item) => !small.includes(item)),
        {
          id: "__other",
          label: "Other",
          value: small.reduce((sum, item) => sum + item.value, 0),
        },
      ]
    : positive;
  const total = parts
    .filter((item) => !hidden.includes(item.id))
    .reduce((sum, item) => sum + item.value, 0);
  const active = parts.find(
    (item) => item.id === (preview ?? pinned) && !hidden.includes(item.id),
  );
  return (
    <figure
      ref={root}
      aria-label={label}
      aria-busy={loading}
      data-slot="donut-chart"
      className={cn("min-w-0", className)}
    >
      <figcaption className="mb-4 text-sm font-medium">{label}</figcaption>
      <ChartMessage loading={loading} error={error} empty={!parts.length} />
      {!error && !!parts.length && (
        <div data-slot="donut-layout">
          <div className="relative mx-auto w-52 max-w-full">
            <svg
              aria-hidden="true"
              viewBox="0 0 200 200"
              className="w-full -rotate-90"
            >
              <circle
                cx="100"
                cy="100"
                r="78"
                fill="none"
                stroke="var(--muted)"
                strokeWidth="20"
              />
              {parts.map((item, index) => {
                const share =
                  hidden.includes(item.id) || !total
                    ? 0
                    : (item.value / total) * 100;
                const offset = parts.slice(0, index).reduce((sum, part) => sum + (hidden.includes(part.id) || !total ? 0 : part.value / total * 100), 0);
                const angle = ((offset + share / 2) / 100) * Math.PI * 2;
                return (
                  <circle
                    key={item.id}
                    data-slot="donut-segment"
                    cx="100"
                    cy="100"
                    r="78"
                    fill="none"
                    stroke={item.color ?? chartColor(index)}
                    strokeWidth={active?.id === item.id ? 24 : 20}
                    pathLength="100"
                    strokeDasharray={`${Math.max(0, share - 0.7)} ${100 - Math.max(0, share - 0.7)}`}
                    strokeDashoffset={-offset}
                    style={{
                      opacity: active && active.id !== item.id ? 0.35 : 1,
                      transform:
                        active?.id === item.id
                          ? `translate(${Math.cos(angle) * 3}px,${Math.sin(angle) * 3}px)`
                          : "translate(0,0)",
                    }}
                    onPointerEnter={() => setPreview(item.id)}
                    onPointerLeave={() => setPreview(null)}
                    onClick={() =>
                      setPinned(pinned === item.id ? null : item.id)
                    }
                  />
                );
              })}
            </svg>
            <div
              className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center"
              aria-hidden="true"
            >
              <span className="max-w-32 truncate text-xs text-muted-foreground">
                {active?.label ?? "Total"}
              </span>
              <AnimatedCounter
                value={active?.value ?? total}
                className="mt-1 text-2xl tracking-tight"
              />
              <span className="mt-1 text-xs text-muted-foreground">
                {active
                  ? `${Math.round((active.value / (total || 1)) * 100)}%`
                  : unit}
              </span>
              {!total && (
                <span className="mt-1 text-xs text-muted-foreground">
                  All hidden
                </span>
              )}
            </div>
          </div>
          <div
            role="group"
            aria-label={`${label} categories`}
            className="grid content-center gap-1"
            onKeyDown={(event) => {
              legendKeys(event);
              if (event.key === "Escape") {
                setPinned(null);
                setPreview(null);
              }
            }}
          >
            {parts.map((item, index) => (
              <div key={item.id} className="flex items-center gap-1">
                <button
                  type="button"
                  data-slot="donut-legend"
                  aria-pressed={!hidden.includes(item.id)}
                  aria-label={`${item.label}, ${numberText(item.value)} ${unit}, ${Math.round((item.value / whole) * 100)} percent${item.id === "__other" ? `, includes ${small.map((part) => part.label).join(", ")}` : ""}`}
                  onClick={() =>
                    setHidden(
                      hidden.includes(item.id)
                        ? hidden.filter((key) => key !== item.id)
                        : [...hidden, item.id],
                    )
                  }
                  onFocus={() => setPreview(item.id)}
                  onBlur={() => setPreview(null)}
                  onPointerEnter={() => setPreview(item.id)}
                  onPointerLeave={() => setPreview(null)}
                  className="flex min-h-11 min-w-0 flex-1 items-center gap-2 rounded-control px-2 text-left text-xs outline-none hover:bg-muted focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-ring"
                >
                  <span
                    aria-hidden="true"
                    className="size-2 shrink-0 rounded-full"
                    style={{ background: item.color ?? chartColor(index) }}
                  />
                  <span className="min-w-0 flex-1 truncate">{item.label}</span>
                  <strong className="font-medium tabular-nums">
                    {numberText(item.value)}
                  </strong>
                  <span className="w-8 text-right tabular-nums text-muted-foreground">
                    {Math.round((item.value / whole) * 100)}%
                  </span>
                </button>
                <button
                  type="button"
                  className="caliper-icon-button text-xs"
                  aria-label={`Pin ${item.label}`}
                  aria-pressed={pinned === item.id}
                  onClick={() => setPinned(pinned === item.id ? null : item.id)}
                >
                  ⌖
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
      <p className="sr-only" role="status">
        {label}. Visible total {numberText(total)} {unit}.
        {active ? ` ${active.label}: ${numberText(active.value)}.` : ""}
      </p>
      <ChartTable
        label={label}
        headers={["Category", "Value", "Share"]}
        rows={positive.map((item) => [
          item.label,
          item.value,
          `${Math.round((item.value / (whole || 1)) * 100)}%`,
        ])}
      />
    </figure>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Milliseconds from a CSS time such as "280ms" or ".28s" (build tools may rewrite one as the other). */
export function cssMs(value: string) {
  const text = value.trim();
  const number = parseFloat(text);
  if (!Number.isFinite(number)) return 0;
  return text.endsWith("ms") ? number : text.endsWith("s") ? number * 1000 : number;
}

/** Reads a duration token (e.g. "--duration-travel") in milliseconds from an element; the tokens resolve to 0 under reduced motion. */
export function tokenMs(element: Element, name: string) {
  return cssMs(getComputedStyle(element).getPropertyValue(name));
}

/* animated-counter.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="counter-shell"] {
    transition: width var(--duration-deliberate) var(--ease-out);
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="counter-shell"] {
      transition: none;
    }
  }
}

/* chart-parts.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="chart-legend-item"] {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    min-height: var(--control-height);
    padding: 0.25rem 0.5rem;
    border-radius: var(--radius-control);
    font-size: 0.75rem;
    color: var(--muted-foreground);
    outline: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }
  [data-slot="chart-legend-item"]:hover,
  [data-slot="chart-legend-item"][data-active="true"] {
    background: var(--muted);
    color: var(--foreground);
  }
  [data-slot="chart-legend-item"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  [data-slot="chart-legend-item"][aria-pressed="false"] {
    opacity: 0.45;
    text-decoration: line-through;
  }
}

/* Shared by animated-tabs.tsx, dock.tsx, donut-chart.tsx, sortable-list.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  .caliper-icon-button {
    display: inline-grid;
    place-items: center;
    flex-shrink: 0;
    min-width: var(--control-height);
    min-height: var(--control-height);
    border-radius: var(--radius-control);
    color: var(--muted-foreground);
    outline: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      scale var(--duration-fast) var(--ease-out);
  }
  .caliper-icon-button:hover {
    background: var(--muted);
    color: var(--foreground);
  }
  .caliper-icon-button:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  .caliper-icon-button:active {
    scale: var(--motion-press-scale);
  }
  .caliper-icon-button:disabled {
    opacity: 0.4;
    pointer-events: none;
  }
}

/* donut-chart.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="donut-legend"][aria-pressed="false"] {
    opacity: 0.45;
    text-decoration: line-through;
  }
  [data-slot="donut-chart"] {
    container-type: inline-size;
  }
  [data-slot="donut-layout"] {
    display: grid;
    gap: 1.5rem;
  }
  @container (min-width:28rem) {
    [data-slot="donut-layout"] {
      grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
    }
  }
  [data-slot="donut-segment"] {
    cursor: pointer;
    transition:
      stroke-dasharray var(--duration-travel) var(--ease-showcase),
      stroke-dashoffset var(--duration-travel) var(--ease-showcase),
      stroke-width var(--duration-normal) var(--ease-out),
      transform var(--duration-normal) var(--ease-out),
      opacity var(--duration-fast) var(--ease-out);
  }
  [data-slot="donut-chart"][data-visible="true"] [data-slot="donut-segment"] {
    animation: caliper-ring-fill var(--duration-showcase) var(--ease-showcase);
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="donut-segment"] {
      transition: none;
      animation: none !important;
    }
  }
}
